import os
from sqlalchemy import (create_engine, MetaData, Table, Column, Integer, String, Boolean,
                        Numeric, DateTime, Date, ForeignKey, CheckConstraint, UniqueConstraint)
from datetime import datetime, timezone

def now(): return datetime.now(timezone.utc).replace(tzinfo=None)
from app.db import engine
meta = MetaData()
stores = Table('stores', meta, Column('id', Integer, primary_key=True), Column('name', String(100), nullable=False), Column('address', String(255), nullable=False))
users = Table('users', meta, Column('id', Integer, primary_key=True), Column('username', String(80), unique=True, nullable=False), Column('password_hash', String(255), nullable=False), Column('role', String(20), nullable=False), Column('name', String(100), nullable=False), Column('email', String(150), nullable=False), Column('phone', String(30), nullable=False, default=''), Column('address', String(255), nullable=False, default=''), Column('vehicle', String(100), nullable=False, default=''), Column('store_id', Integer, ForeignKey('stores.id')), Column('department', String(80), nullable=False, default=''), Column('active', Boolean, nullable=False, default=True), CheckConstraint("role IN ('customer','employee','manager')"))
sessions = Table('sessions', meta, Column('token_hash', String(64), primary_key=True), Column('user_id', Integer, ForeignKey('users.id'), nullable=False), Column('expires', DateTime, nullable=False))
suppliers = Table('suppliers', meta, Column('id', Integer, primary_key=True), Column('name', String(100), nullable=False), Column('email', String(150), nullable=False))
parts = Table('parts', meta, Column('id', Integer, primary_key=True), Column('sku', String(50), nullable=False, unique=True), Column('name', String(120), nullable=False), Column('category', String(80), nullable=False), Column('description', String(1000), nullable=False), Column('condition', String(20), nullable=False), Column('price', Numeric(10,2), nullable=False), Column('supplier_id', Integer, ForeignKey('suppliers.id'), nullable=False), Column('active', Boolean, nullable=False, default=True), CheckConstraint('price >= 0'), CheckConstraint("`condition` IN ('new','rebuilt')"))
inventory = Table('inventory', meta, Column('store_id', Integer, ForeignKey('stores.id'), primary_key=True), Column('part_id', Integer, ForeignKey('parts.id'), primary_key=True), Column('quantity', Integer, nullable=False, default=0), Column('reorder_level', Integer, nullable=False, default=5), CheckConstraint('quantity >= 0'), CheckConstraint('reorder_level >= 0'))
orders = Table('orders', meta, Column('id', Integer, primary_key=True), Column('customer_id', Integer, ForeignKey('users.id'), nullable=False), Column('store_id', Integer, ForeignKey('stores.id'), nullable=False), Column('created_at', DateTime, nullable=False, default=now), Column('status', String(25), nullable=False, default='placed'), Column('delivery_date', Date), Column('delivered_at', DateTime), Column('shipping_address', String(255), nullable=False), CheckConstraint("status IN ('placed','shipped','delivered','cancelled','returned')"))
order_items = Table('order_items', meta, Column('order_id', Integer, ForeignKey('orders.id'), primary_key=True), Column('part_id', Integer, ForeignKey('parts.id'), primary_key=True), Column('quantity', Integer, nullable=False), Column('unit_price', Numeric(10,2), nullable=False), CheckConstraint('quantity > 0'), CheckConstraint('unit_price >= 0'))
payments = Table('payments', meta, Column('id', Integer, primary_key=True), Column('order_id', Integer, ForeignKey('orders.id'), unique=True, nullable=False), Column('method', String(30), nullable=False), Column('status', String(30), nullable=False), Column('amount', Numeric(12,2), nullable=False), Column('reference', String(100), nullable=False), CheckConstraint('amount >= 0'))
purchases = Table('purchases', meta, Column('id', Integer, primary_key=True), Column('store_id', Integer, ForeignKey('stores.id'), nullable=False), Column('part_id', Integer, ForeignKey('parts.id'), nullable=False), Column('supplier_id', Integer, ForeignKey('suppliers.id'), nullable=False), Column('employee_id', Integer, ForeignKey('users.id'), nullable=False), Column('quantity', Integer, nullable=False), Column('created_at', DateTime, nullable=False, default=now), Column('status', String(20), nullable=False, default='ordered'), CheckConstraint('quantity > 0'), CheckConstraint("status IN ('ordered','received','cancelled')"))
from sqlalchemy import Index
Index('ix_orders_date', orders.c.created_at)
Index('ix_orders_customer', orders.c.customer_id)
